import{z as s,x as m,o as r,c as O,q as i,j as p,D as l,d as o,s as n,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"ORPO 原文","description":"","frontmatter":{"title":"ORPO 原文","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/orpo-paper.md","filePath":"llm/orpo-paper.md","lastUpdated":1791413859000}'),d={name:"llm/orpo-paper.md"};function h(P,a,B,A,L,_){const t=m("Mermaid");return r(),O("div",null,[a[2]||(a[2]=i('<h1 id="orpo-原文" tabindex="-1">ORPO 原文 <a class="header-anchor" href="#orpo-原文" aria-label="Permalink to &quot;ORPO 原文&quot;">​</a></h1><div class="epigraph"><p>单体偏好优化：同一项损失里既拟合喜欢的回答，又用几率比压低不喜欢的回答，不必另存参考模型，也不必先做完 SFT 再切 DPO。</p><footer>—— Hong, Lee, Thorne，ORPO: Monolithic Preference Optimization without Reference Model，EMNLP 2024</footer></div><p>已有 <a href="/llm/orpo">ORPO</a> 篇写几率定义、\\(\\lambda\\) 与长度陷阱、以及和 SimPO / DPO 的正则分工。本篇钉 Hong、Lee、Thorne 的 EMNLP 2024 原文（arXiv:2403.07691）：他们要替换的流程裂缝是什么、几率比相对裸对数差的理论叙事、实验在哪些模型与基准上支持「单阶段无参考」，以及哪些数字不能从 AlpacaEval 一行外推成定律。配方与掩码仍见前一篇。<span class="marginnote">monolithic（单体）翻译过来就是「一块整的」：SFT 与偏好对齐不再分成两个阶段、两个检查点、两份权重，而是同一批成对数据、同一份参数、一次训练跑完。标题里 without a Reference Model 说的就是同一件事在训练图里的版本。</span></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>InstructGPT 式后训练拆成 SFT 再 DPO/PPO。拆开的代价有三。显存：DPO 的隐含奖励是 \\(\\log(\\pi/\\pi_{\\mathrm{ref}})\\)，训练图驻留两份模型。流程：必须先得到一份当作参照的 SFT 检查点，早停、学习率、过拟合点都要切一次。目标分裂：SFT 只抬 \\(y_w\\) 的绝对似然，DPO 只抬相对比，衔接不好会出现「对比拉开了、喜欢的回答变糊」或「SFT 过拟合模板、DPO 再拧到另一套套话」。小团队在单卡 LoRA 上，第二份模型直接决定做不做偏好。</p><p>无参考之后，裸的 \\(\\log\\pi(y_w)-\\log\\pi(y_l)\\) 缺少「不许整体跑飞」的锚，纯对比可以把两条似然一起压低。作者要的单体目标是：同一批成对数据、同一份权重、一次训练，既有语言建模项，又有不依赖 \\(\\pi_{\\mathrm{ref}}\\) 的对比项，且对比在 \\(p\\to 1\\) 时不要像未归一对数差那样无限加码。</p><h3 id="参考模型在-dpo-里实际买到了什么" tabindex="-1">参考模型在 DPO 里实际买到了什么 <a class="header-anchor" href="#参考模型在-dpo-里实际买到了什么" aria-label="Permalink to &quot;参考模型在 DPO 里实际买到了什么&quot;">​</a></h3><p>参考差消掉两侧共同的模式（套话、模板），并提供 KL 意义下的偏离代价。删掉它，等于同时丢掉校准器与锚。ORPO 不否认 \\(\\beta\\) 在 DPO 里的数学角色，见 <a href="/llm/dpo-beta-ref">参考模型与 β</a>；它声称的是：若把 SFT 项留在损失里，锚可以改由 \\(y_w\\) 的 NLL 承担，校准器那一部分则放弃——这是显存与流程换来的语义变窄，原文把它写成优点，工程上必须当代价。</p><p><span class="marginnote">「无参考」不是无正则。正则从 \\(\\mathrm{KL}(\\pi\\|\\pi_{\\mathrm{ref}})\\) 换成了对数据集中 \\(y_w\\) 的最大似然。未出现在喜欢回答里的合理变体，没有显式保护。这是单体方案的盲区，不是实现漏写 KL。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>序列概率 \\(p_\\theta(y\\mid x)\\) 的几率为 \\(p/(1-p)\\)。成对样本上定义对数几率比</p> \\[\\log\\mathrm{OR}_\\theta=\\log\\frac{\\mathrm{odds}_\\theta(y_w\\mid x)}{\\mathrm{odds}_\\theta(y_l\\mid x)}. \\]<p>总损失为喜欢回答上的因果 NLL 加上加权的 \\(-\\log\\sigma(\\log\\mathrm{OR})\\)。第一项与普通 SFT 相同，chat 模板与提示掩码相同；第二项推动 \\(y_w\\) 相对 \\(y_l\\) 的几率，权重 \\(\\lambda\\)。没有冻结参照，没有 KL 估计。训练可以从基座或轻度指令化检查点一次做完，这就是标题里的 monolithic。</p><h3 id="原文的理论叙事-几率比如何分流梯度" tabindex="-1">原文的理论叙事：几率比如何分流梯度 <a class="header-anchor" href="#原文的理论叙事-几率比如何分流梯度" aria-label="Permalink to &quot;原文的理论叙事：几率比如何分流梯度&quot;">​</a></h3><p>几率在 \\(p\\to 1\\) 时趋于无穷，已经很高的 \\(y_w\\) 再抬绝对概率的边际下降，对比梯度更多落到压低 \\(y_l\\)。作者把这解释成：SFT 项负责「会说喜欢的话」，OR 项负责「相对拒绝样本拉开」，两者在饱和区自然分工。这与 KTO 增益侧凹神似，但推导来自几率变换，不是前景理论。序列概率用 token 乘积，实现必须在对数空间；极长序列上 \\(p\\approx 0\\)，几率退化成 \\(p\\)，OR 退回普通对数差，饱和好处消失——原文以序列概率为准，长度平均是后来的工程修补。<span class="marginnote">数字实例：设 \\(p(y_w)=0.9\\)、\\(p(y_l)=0.3\\)，几率分别是 \\(9\\) 与 \\(0.43\\)，对数几率比约 \\(\\log(21)\\approx3\\)。若把 \\(y_l\\) 压到 \\(0.1\\)，几率变 \\(0.11\\)，比值升到约 \\(82\\)——压分母远比抬分子见效快，这就是饱和区梯度流向不喜欢侧的算术。</span></p>',15)),(r(),p(E,null,{default:l(()=>[n(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAIR%5B%22%E6%88%90%E5%AF%B9%20(x%2C%20yw%2C%20yl)%22%5D%20--%3E%20NLL%5B%22SFT%EF%BC%9A-log%20%CF%80(yw)%22%5D%0A%20%20PAIR%20--%3E%20OR%5B%22log%20%E5%87%A0%E7%8E%87%E6%AF%94%22%5D%0A%20%20NLL%20--%3E%20MONO%5B%22%E5%8A%A0%E6%9D%83%E5%92%8C%EF%BC%8C%E4%B8%80%E4%BB%BD%20%CF%80%CE%B8%22%5D%0A%20%20OR%20--%3E%20MONO%0A%20%20REF%5B%22%E6%97%A0%20%CF%80ref%22%5D%20-.-%3E%20MONO%0A%20%20MONO%20--%3E%20STAGE%5B%22%E5%8D%95%E9%98%B6%E6%AE%B5%E7%BB%93%E6%9D%9F%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h3",{id:"实验支持什么、不支持什么",tabindex:"-1"},[o("实验支持什么、不支持什么 "),e("a",{class:"header-anchor",href:"#实验支持什么、不支持什么","aria-label":'Permalink to "实验支持什么、不支持什么"'},"​")],-1)),a[4]||(a[4]=e("p",null,"原文在 Phi-2、Llama-2、Mistral 等规模上，用指令偏好数据对照 SFT、SFT+DPO 等。叙事是：单阶段 ORPO 达到或超过「先 SFT 再 DPO」的指令跟随指标，同时省掉参考前向。AlpacaEval 一类 GPT 裁判分随裁判版本与长度控制剧烈变化，只能当论文表内相对排序，不能抄成跨年的绝对能力。安全、多语、工具调用不是主表。\\(\\lambda\\) 过小接近纯 SFT，过大则流畅性掉、开始学「只要和 \\(y_l\\) 不同」——原文把 \\(\\lambda\\) 当需要扫的超参，没有跨模型定理值。",-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"SFT 项阻止为了拉大 OR 而把 \\(y_w\\) 自己打塌：喜欢侧概率下降会立刻被 NLL 惩罚。这不是 KL 的同构物，保护集合只是数据里的 \\(y_w\\)。OR 项对噪声对敏感：若 \\(y_l\\) 其实可接受，对比项在打压合理回答，拒绝率与多样性一起坏。单体训练容易让日志只看总损失；原文方法节隐含的监控是两项分开看——NLL 降而 OR 不降，是对比没学上；OR 降而 NLL 升，是牺牲拟合拉差距。",-1)),(r(),p(E,null,{default:l(()=>[n(t,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20DPO%5B%22DPO%EF%BC%9A%CF%80%CE%B8%20%2B%20%CF%80ref%20%E4%B8%A4%E4%BB%BD%E6%9D%83%E9%87%8D%22%5D%20--%3E%20KL%5B%22%E9%94%9A%EF%BC%9AKL(%CF%80%CE%B8%E2%80%96%CF%80ref)%22%5D%0A%20%20KL%20--%3E%20C1%5B%22%E6%98%BE%E5%AD%98%E7%BA%A6%E4%B8%A4%E5%80%8D%EF%BC%8C%E9%A1%BB%E5%85%88%E6%9C%89%20SFT%20%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%0A%20%20ORPO%5B%22ORPO%EF%BC%9A%E5%8F%AA%E6%9C%89%20%CF%80%CE%B8%20%E4%B8%80%E4%BB%BD%22%5D%20--%3E%20NLL%5B%22%E9%94%9A%EF%BC%9ANLL(yw)%20%E7%95%99%E5%9C%A8%E6%8D%9F%E5%A4%B1%E9%87%8C%22%5D%0A%20%20NLL%20--%3E%20C2%5B%22%E5%8F%AA%E4%BF%9D%E6%8A%A4%E6%95%B0%E6%8D%AE%E9%9B%86%E4%B8%AD%E5%87%BA%E7%8E%B0%E8%BF%87%E7%9A%84%20yw%22%5D%0A%20%20ORPO%20--%3E%20OR%5B%22OR%20%E9%A1%B9%E6%8B%89%E5%BC%80%20yw%20%E7%9B%B8%E5%AF%B9%20yl%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p>从已 SFT 的检查点再跑 ORPO，NLL 项会重复拟合已经学过的 \\(y_w\\)，有过拟合模板风险，应少 epoch 或加大 \\(\\lambda\\)、换新偏好对。从基座直训时，NLL 是必要语言监督，不能只留 OR。这两条流程在论文的「不必先 SFT」口号下仍然分叉，落地篇写得更硬，原文实验更多是从指令模型或基座各跑一套对照。</p><p><span class="marginnote">几率比不消除长度偏置。更长的 \\(y_w\\) 序列概率更小，odds 跟着变。论文主结果若未做长度控制的裁判，可能部分来自话多。产品监控应单列生成长度，不能把 AlpacaEval 原始胜率当成已校准偏好。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>省一半驻留权重，在 LoRA 微调里尤其明显。换来的是：无参照校准、对 \\(y_w\\) 过拟合更敏感、必须成对数据、序列概率数值要 clamp。ORPO 吃不了 <a href="/llm/kto">KTO</a> 的单条点赞；把无对照日志配随机负例，几率比变成「和噪声比」。也不替代奖励模型管线：要在线采样再打分，仍是 RLHF。</p><p>与 <a href="/llm/simpo">SimPO</a> 同属无参考，但锚不同：ORPO 是 NLL，SimPO 是平均对数概率加间隔 \\(\\gamma\\)。与 <a href="/llm/slic">SLiC</a> 同有监督项，但 SLiC 用铰链、常需要多样本候选。选择应先看能不能放参考、再看要不要显式 SFT 项，而不是看 EMNLP 年份。<span class="marginnote">初学者容易把「无参考」读成「无正则、随便跑」。实际上 ORPO 把正则从参考模型的 KL 换成了对数据集中喜欢回答的最大似然：约束还在，只是保护范围从「参考分布下所有合理说法」缩小到「训练集里出现过的 \\(y_w\\)」。这是换锚，不是拆锚。</span></p><p><span class="marginnote">出处钉 Jiwoo Hong、Noah Lee、James Thorne，KAIST，EMNLP 2024，arXiv:2403.07691。标题 without a Reference Model 容易被读成「对齐不需要 SFT 分布」。正确读法是：训练图不加载第二份权重，分布锚改由喜欢回答的 NLL 承担。</span></p><h3 id="何时不必上这篇原文" tabindex="-1">何时不必上这篇原文 <a class="header-anchor" href="#何时不必上这篇原文" aria-label="Permalink to &quot;何时不必上这篇原文&quot;">​</a></h3><p>只会改 TRL 里的 <code>ORPOTrainer</code>、扫 \\(\\lambda\\)，读 <a href="/llm/orpo">ORPO</a>。需要引用单体流程相对 SFT+DPO 的实验表、需要向评审解释为何几率而不是裸对数差，再读原文。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ORPO 原文主张单阶段、无参考：NLL\\((y_w)\\) + 几率比对比，一份权重做完偏好。</li><li>几率变换在高概率区改变梯度分工；极长序列上会退化成对数差。</li><li>实验支持「省参考仍可达到同数据 DPO 量级的指令跟随」，不是安全对齐完备方案。</li><li>正则只保护数据集中的 \\(y_w\\)；长度与噪声对仍在。</li><li>与 SimPO、SLiC、DPO 的差别是锚的语义，不是名字新旧。</li><li>出处：Hong, Lee, Thorne，<em>ORPO: Monolithic Preference Optimization without Reference Model</em>，EMNLP 2024；落地对照见 <a href="/llm/orpo">ORPO</a>。</li></ul>',10))])}const F=s(d,[["render",h]]);export{T as __pageData,F as default};
